{
  "schema_version": 1,
  "observations": [
    {
      "key": "obs_1",
      "facet": "term",
      "statement": "Safe methods are request methods whose defined semantics are essentially read-only, meaning the client does not request or expect any state change on the origin server as a result of applying the method.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_2",
      "facet": "property",
      "statement": "The definition of safe methods does not prevent an implementation from including behavior that is potentially harmful, not entirely read-only, or causes side effects.",
      "start_line": 5,
      "end_line": 5
    },
    {
      "key": "obs_3",
      "facet": "property",
      "statement": "For a method to be considered safe, it is important that the client did not request additional behavior and cannot be held accountable for it.",
      "start_line": 5,
      "end_line": 5
    },
    {
      "key": "obs_4",
      "facet": "reference",
      "statement": "GET, HEAD, OPTIONS, and TRACE are defined to be safe request methods by this specification.",
      "start_line": 7,
      "end_line": 7
    }
  ],
  "claims": [],
  "questions": []
}
